import{z as n,x as i,o as B,c as l,q as e,j as s,D as a,d as r,s as o,S as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"虚拟内存的实现","description":"","frontmatter":{"title":"虚拟内存的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/osk-vm-implementation.md","filePath":"cs/osk-vm-implementation.md","lastUpdated":1791413859000}'),p={name:"cs/osk-vm-implementation.md"};function d(m,E,C,c,h,T){const A=i("Mermaid");return B(),l("div",null,[E[2]||(E[2]=e('<h1 id="虚拟内存的实现" tabindex="-1">虚拟内存的实现 <a class="header-anchor" href="#虚拟内存的实现" aria-label="Permalink to &quot;虚拟内存的实现&quot;">​</a></h1><div class="epigraph"><p>缺页处理程序是内核里最常见的一次现挂现解：每一页的合法性与内容，都拖到第一次触碰才决定。</p><footer>—— 据 Arpaci-Dusseau, OSTEP；Tanenbaum and Bos, Modern Operating Systems 整理</footer></div><p><a href="/cs/osk-process-scheduler">上一课</a>把切换的执行流接通了，switch_mm 换的正是本课的对象：进程的地址空间。主干已经给过零件——<a href="/cs/process-addrspace-tour">进程地址空间一览</a>画了用户地图，<a href="/cs/page-fault-path">缺页路径</a>与<a href="/cs/demand-paging">按需调页</a>讲了缺页语义，<a href="/cs/cow-fork">写时复制</a>给了 fork 的偷懒。缺口是把零件装配成内核里真正跑的那组结构：地址空间对象、区间树、页表、反向映射怎么互相咬合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户地图上的每一段只是「这里可以有什么」的声明，页表才是「现在有什么」。实现要回答两个方向的问题：正向，一个缺页地址进来，内核如何在微秒级判定它是哪种缺页——文件页、匿名页、写时复制还是越界；反向，回收一页时如何找到「谁映射着它」。不这么做会错在哪：把区间当页表用，每次地址翻译都要线性扫描区间表；没有反向映射，回收一页要扫遍所有进程的全部虚拟地址——回收这个功能在工程上根本不成立。</p><p><span class="marginnote">直觉类比：VMA 像租房合同——只声明「这段地址可以怎么用」；页表才是实际交钥匙——具体哪一页此刻真的在内存里。mmap 只是签合同，一页不分；真正「入住」要等第一次触碰触发缺页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>地址空间对象挂在上一课的进程控制块上；区间（VMA）按地址组织成有序结构，mmap、brk、栈增长都只是插入与合并区间，一页都不分配。缺页入口按四级分流：地址落在某个区间里吗——不在就是段错误，除非贴近栈指针（那算隐式扩栈）；权限对吗——写只读段转发为信号；页表项为空吗——按区间类型填页，文件页从页缓存读入，匿名页给零页或现分配；页表项在但只读而区间可写吗——复制页面并改写为可写，这就是写时复制的兑现点。填完页表项刷新对应 TLB，重执行触发缺页的那条指令。fork 之所以便宜，也因为装配只在区间层复制加页表复制加写保护，内容零拷贝。</p>',8)),(B(),s(t,null,{default:a(()=>[o(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAULT%5B%22%E7%BC%BA%E9%A1%B5%E5%BC%82%E5%B8%B8%22%5D%20--%3E%20INV%7B%22%E5%9C%B0%E5%9D%80%E5%9C%A8%E6%9F%90%E5%8C%BA%E9%97%B4%E5%86%85%3F%22%7D%0A%20%20INV%20--%3E%7C%E5%90%A6%7C%20SEG%5B%22%E6%AE%B5%E9%94%99%E8%AF%AF%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20INV%20--%3E%7C%E6%98%AF%7C%20PERM%7B%22%E6%9D%83%E9%99%90%E5%8C%B9%E9%85%8D%3F%22%7D%0A%20%20PERM%20--%3E%7C%E5%90%A6%7C%20SIG%5B%22%E8%B6%8A%E6%9D%83%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20PERM%20--%3E%7C%E6%98%AF%7C%20PTE%7B%22%E9%A1%B5%E8%A1%A8%E9%A1%B9%E4%B8%BA%E7%A9%BA%3F%22%7D%0A%20%20PTE%20--%3E%7C%E6%98%AF%7C%20FILL%5B%22%E6%8C%89%E7%B1%BB%E5%9E%8B%E5%A1%AB%E9%A1%B5%EF%BC%9A%E6%96%87%E4%BB%B6%E9%A1%B5%E6%88%96%E5%8C%BF%E5%90%8D%E9%A1%B5%22%5D%0A%20%20PTE%20--%3E%7C%E5%90%A6%EF%BC%8C%E5%8F%AA%E8%AF%BB%E5%8D%B4%E5%86%99%7C%20COW%5B%22%E5%A4%8D%E5%88%B6%E9%A1%B5%E9%9D%A2%EF%BC%8C%E6%94%B9%E5%86%99%E9%A1%B5%E8%A1%A8%E9%A1%B9%22%5D%0A%20%20FILL%20--%3E%20TLB%5B%22%E5%88%B7%E6%96%B0%20TLB%EF%BC%8C%E9%87%8D%E6%89%A7%E8%A1%8C%E6%8C%87%E4%BB%A4%22%5D%0A%20%20COW%20--%3E%20TLB%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反向映射让回收成为可能：物理页的元数据里记录映射计数与归属——匿名页经区间链、文件页经地址空间的页索引——回收时沿它逐个清除页表项。它为什么必须存在：置换策略（<a href="/cs/anon-vs-file-page">匿名页对文件页</a>、<a href="/cs/memory-reclaim">回收</a>、<a href="/cs/oom-killer">OOM</a>）都在物理页面上工作，而映射关系天然长在虚拟侧；没有这座反向桥，候选集合构造不出来。跨 CPU 的一致性也在这层闭合：清了别处的页表项还要做 <a href="/cs/tlb-shootdown">TLB shootdown</a>，否则旧翻译还会指向已被拿走的页。零页是同一机制的极端用法：几百 MB 的未写内存共享一页只读零页，第一次写才摊开。</p>',2)),(B(),s(t,null,{default:a(()=>[o(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20PG%5B%22%E7%89%A9%E7%90%86%E9%A1%B5%E8%A2%AB%E9%80%89%E4%B8%AD%E5%9B%9E%E6%94%B6%22%5D%20--%3E%20META%5B%22%E6%9F%A5%E9%A1%B5%E5%85%83%E6%95%B0%E6%8D%AE%EF%BC%9A%E6%98%A0%E5%B0%84%E8%AE%A1%E6%95%B0%E4%B8%8E%E5%BD%92%E5%B1%9E%22%5D%0A%20%20META%20--%3E%20T%7B%22%E9%A1%B5%E9%9D%A2%E6%98%AF%E4%BB%80%E4%B9%88%E7%B1%BB%E5%9E%8B%3F%22%7D%0A%20%20T%20--%3E%7C%22%E5%8C%BF%E5%90%8D%E9%A1%B5%22%7C%20VA%5B%22%E6%B2%BF%E5%8C%BA%E9%97%B4%E9%93%BE%E6%89%BE%E6%98%A0%E5%B0%84%E5%AE%83%E7%9A%84%20VMA%22%5D%0A%20%20T%20--%3E%7C%22%E6%96%87%E4%BB%B6%E9%A1%B5%22%7C%20AS%5B%22%E6%B2%BF%E5%9C%B0%E5%9D%80%E7%A9%BA%E9%97%B4%E6%8C%89%E9%A1%B5%E5%81%8F%E7%A7%BB%E6%89%BE%E6%98%A0%E5%B0%84%22%5D%0A%20%20VA%20--%3E%20CLR%5B%22%E5%AF%B9%E6%AF%8F%E4%B8%AA%E6%98%A0%E5%B0%84%E8%80%85%E6%B8%85%E9%99%A4%E5%AF%B9%E5%BA%94%E9%A1%B5%E8%A1%A8%E9%A1%B9%22%5D%0A%20%20AS%20--%3E%20CLR%0A%20%20CLR%20--%3E%20TLB%5B%22%E5%90%91%E5%85%B6%E4%BB%96%20CPU%20%E5%8F%91%20TLB%20%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20TLB%20--%3E%20FREE%5B%22%E6%98%A0%E5%B0%84%E8%AE%A1%E6%95%B0%E5%BD%92%E9%9B%B6%EF%BC%8C%E9%A1%B5%E5%8F%AF%E7%A7%BB%E8%B5%B0%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">数字实例：x86-64 的页表项是 8 字节，一页 4 KB 正好装 512 个表项；48 位虚拟地址按 9+9+9+9+12 切成四级索引，软件查一次地址要逐级读四张表——这正是 TLB 缓存翻译值得存在的原因：命中时一步到位。</span></p><p><span class="marginnote">术语翻译：TLB shootdown 就是「让别的 CPU 作废旧翻译」——一个核改了页表，其他核的 TLB 里可能还留着旧地址映射，必须挨个发中断通知作废；漏发一个，那个核就会读到早已被挪走的页。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>页表格式与 TLB 层次是体系结构课的对象，本课只管内核侧的组织；swap 设备是 <a href="/cs/swap-device">swap</a> 的对象，按需错页服务是 <a href="/cs/userfaultfd">userfaultfd</a> 的对象，都只引用。大页让「一页」的粒度可变，装配逻辑不变但每一级判断都多一条分支。最后别把缺页当异常：fork 之后第一次写、程序首次访问堆与文件，走的都是缺页——它是设计出来的高频路径，缺页处理程序常是内核里被调用最频繁的复杂函数之一，这是按需调页买来的便宜，不是故障。</p><p><span class="marginnote">匿名页第一次读常映射到一张全系统共享的零页：读它永远得零，第一次写才触发复制。没有这张零页，大块 BSS 与刚申请的堆会在映射时刻就消耗等量物理内存，按需调页就名存实亡。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>地址空间对象与区间是声明，页表是现挂现解；mmap 只造声明，不造页。</li><li>缺页入口按「区间内、权限、页表项空、写时复制」四级分流。</li><li>反向映射把物理页连回映射它的区间，置换与回收才可构造。</li><li>fork 的便宜来自区间加页表加写保护，内容零拷贝；零页是同一机制的极端。</li><li>出处：Arpaci-Dusseau, <em>OSTEP</em>；Tanenbaum and Bos, <em>Modern Operating Systems</em>；Linux MM 子系统骨架。</li></ul>',7))])}const F=n(p,[["render",d]]);export{D as __pageData,F as default};
